SELECT 'SEQ' AS kind, SEQUENCE_NAME AS obj FROM ALL_SEQUENCES WHERE UPPER(SEQUENCE_OWNER)='ZING_DOCTOR_DB_PROD' AND UPPER(SEQUENCE_NAME) LIKE '%PRONE%' UNION ALL SELECT 'TAB', TABLE_NAME FROM ALL_TABLES WHERE UPPER(OWNER)='ZING_DOCTOR_DB_PROD' AND UPPER(TABLE_NAME) LIKE '%PRONE%' ORDER BY 1 DESC, 2;
